package app.noir.mobile;

import android.app.job.*;
import android.content.*;
import android.net.*;
import android.os.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.util.*;

public final class PhoneReadyJob extends JobService {
 public static final int JOB_ID=708,REFILL_ID=709;
 static final java.util.concurrent.Semaphore RUN=new java.util.concurrent.Semaphore(1);volatile boolean ownsRun;
 volatile boolean stopped;Thread worker;DownloadStore captured;
 static PhoneReady policy(DataStore data){return PhoneReady.at(data.context.getFilesDir());}
 static List<JSONObject> plan(DataStore data){JSONObject shows=policy(data).keepReadyJson();List<JSONObject> items=PhoneReady.mergeSchedules(DataStore.objects(data.itemsShared()),shows,data.settings().optJSONObject("schedules"));return PhoneReady.select(items,shows,data.now());}
 public static JobInfo jobInfo(Context c){return new JobInfo.Builder(JOB_ID,new ComponentName(c,PhoneReadyJob.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_UNMETERED).setRequiresCharging(true).setPeriodic(6*3600000L).setPersisted(true).build();}
 public static void schedule(Context c){try{DataStore data=NoirApp.data;if(data==null)return;JobScheduler scheduler=c.getSystemService(JobScheduler.class);if(policy(data).enabled()){if(scheduler.getPendingJob(JOB_ID)==null)scheduler.schedule(jobInfo(c));}else {scheduler.cancel(JOB_ID);scheduler.cancel(REFILL_ID);}}catch(RuntimeException ignored){/* Manager installs the manifest entry. */}}
 public static void refill(Context c){schedule(c);DataStore data=NoirApp.data;if(data==null||!policy(data).enabled())return;data.images.execute(()->policy(data).planned(plan(data)));try{JobScheduler jobs=c.getSystemService(JobScheduler.class);if(jobs.getPendingJob(REFILL_ID)!=null)return;Calendar now=Calendar.getInstance(),next=(Calendar)now.clone();long delay=0;if(!PhoneReady.overnight(now.get(Calendar.HOUR_OF_DAY))){next.add(Calendar.DAY_OF_YEAR,1);next.set(Calendar.HOUR_OF_DAY,0);next.set(Calendar.MINUTE,0);next.set(Calendar.SECOND,0);delay=next.getTimeInMillis()-now.getTimeInMillis();}jobs.schedule(new JobInfo.Builder(REFILL_ID,new ComponentName(c,PhoneReadyJob.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_UNMETERED).setRequiresCharging(true).setMinimumLatency(delay).setPersisted(true).build());}catch(RuntimeException ignored){}}
 static String conditions(Context c){if(!PhoneReady.overnight(Calendar.getInstance().get(Calendar.HOUR_OF_DAY)))return "Waiting for overnight hours (00:00–06:00)";BatteryManager battery=c.getSystemService(BatteryManager.class);if(battery==null||!battery.isCharging())return "Waiting for charging";ConnectivityManager cm=c.getSystemService(ConnectivityManager.class);NetworkCapabilities nc=cm==null?null:cm.getNetworkCapabilities(cm.getActiveNetwork());if(nc==null||!nc.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)||!nc.hasCapability(NetworkCapabilities.NET_CAPABILITY_NOT_METERED)||!nc.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET))return "Waiting for unmetered Wi-Fi";return "";}
 static String allowed(DataStore data,DownloadStore store){PhoneReady p=policy(data);if(data!=NoirApp.data||store!=NoirApp.downloads)return "Phone profile changed";if(!p.enabled())return "Keep ready is off";if(p.paused())return "Preparation paused";return conditions(data.context);}
 @Override public boolean onStartJob(JobParameters parameters){if(worker!=null&&worker.isAlive())return false;stopped=false;DataStore data=NoirApp.data;captured=NoirApp.downloads;worker=new Thread(()->{try{if(RUN.tryAcquire()){ownsRun=true;try{run(data,captured);}finally{ownsRun=false;RUN.release();}}}catch(Exception e){policy(data).log("","Preparation interrupted; retrying later");}finally{jobFinished(parameters,false);}},"Noir-keep-ready");worker.start();return true;}
 @Override public boolean onStopJob(JobParameters parameters){stopped=true;if(ownsRun&&captured!=null){JSONObject j=captured.job(captured.activeId);if(j!=null&&j.optBoolean("readyManaged"))captured.pause(j.optString("id"));}if(worker!=null)worker.interrupt();return true;}
 void run(DataStore data,DownloadStore store)throws Exception{PhoneReady p=policy(data);String reason=allowed(data,store);if(!reason.isEmpty()){p.blocked(reason);return;}cleanup(data,store,p);List<JSONObject> plan=plan(data);p.planned(plan);p.blocked("");
  for(JSONObject item:plan){if(stopped)return;if(!store.activeId.isEmpty()){p.blocked("Waiting for phone downloads to finish");return;}reason=allowed(data,store);if(!reason.isEmpty()){p.blocked(reason);return;}String id=item.optString("id");JSONObject old=store.job(id);if(!data.localFile(id).isEmpty()||old!=null&&(!old.optBoolean("readyManaged")||old.optString("status").equals("complete")))continue;if(!p.canRetry(id,System.currentTimeMillis()))continue;
   try{
    boolean copied=false;if(data.paired()&&lan(data.address())){try{long size=pcSize(data,id);reason=storage(store,p,id,size);if(!reason.isEmpty()){p.blocked(reason);return;}if(store.enqueueReady(item,null,size)){p.log(id,"Copying from your PC over LAN");store.transferReady(id,j->{},()->!stopped&&allowed(data,store).isEmpty()&&p.keepReadyJson().has(item.optString("group")));copied=store.job(id).optString("status").equals("complete");}}catch(Exception e){p.log(id,"PC copy unavailable; checking phone sources");}}
    if(copied){p.log(id,"Ready to watch offline");continue;}if(stopped||!allowed(data,store).isEmpty())return;
    if(old!=null){store.queueReady(id);store.transferReady(id,j->{},()->!stopped&&allowed(data,store).isEmpty()&&p.keepReadyJson().has(item.optString("group")));if(store.job(id).optString("status").equals("complete")){p.log(id,"Ready to watch offline");continue;}if(!allowed(data,store).isEmpty())return;}
    PhoneDownloadProvider provider=store.providers.apply(new PhoneDownloadSettings(data.context).load());List<JSONObject> candidates=readySources(provider,item);JSONObject chosen=null;String storageBlock="";for(JSONObject c:candidates){reason=storage(store,p,id,c.optLong("size"));if(reason.isEmpty()){chosen=c;break;}storageBlock=reason;}
    if(chosen==null){if(!storageBlock.isEmpty()){p.blocked(storageBlock);return;}p.log(id,"Waiting for a confirmed cached single-episode source");p.retry(id,System.currentTimeMillis());continue;}
    if(store.enqueueReady(item,chosen,chosen.optLong("size"))){p.log(id,"Downloading a cached source on this phone");store.transferReady(id,j->{},()->!stopped&&allowed(data,store).isEmpty()&&p.keepReadyJson().has(item.optString("group")));JSONObject result=store.job(id);if(result.optString("status").equals("complete"))p.log(id,"Ready to watch offline");else{p.log(id,"Preparation interrupted; retrying later");p.retry(id,System.currentTimeMillis());}}
   }catch(Exception e){p.log(id,"Ready source unavailable; retrying later");p.retry(id,System.currentTimeMillis());}
  }
 }
 static List<JSONObject> readySources(PhoneDownloadProvider provider,JSONObject item)throws Exception{List<JSONObject> safe=new ArrayList<>();for(JSONObject c:provider.search(item))if(c.optBoolean("cached")&&!c.optBoolean("pack")&&c.optString("service").equals("direct")&&c.optLong("size")>0)safe.add(c);return PhoneDownloadProvider.ranked(safe,provider.config,"");}
 static boolean lan(String address){try{String host=new URI(address.contains("://")?address:"https://"+address).getHost();if(host==null)return false;for(InetAddress a:InetAddress.getAllByName(host))if(a.isSiteLocalAddress()||a.isLinkLocalAddress())return true;}catch(Exception ignored){}return false;}
 static long pcSize(DataStore data,String id)throws Exception{HttpURLConnection c=data.media(id,"bytes=0-0");try{c.setConnectTimeout(10000);c.setReadTimeout(10000);int status=c.getResponseCode();long size=status==206?DownloadStore.range(c.getHeaderField("Content-Range"))[2]:status==200?c.getContentLengthLong():0;if(size<=0)throw new IOException();return size;}finally{c.disconnect();}}
 static long used(DownloadStore store){long total=0;ProfileStore profiles=new ProfileStore(store.context);for(JSONObject profile:DataStore.objects(profiles.list())){Context c=ProfileStore.context(store.context,profile.optString("id"));File base=c.getExternalFilesDir(null);File dir=new File(base==null?c.getFilesDir():base,"offline");File[] files=dir.listFiles();if(files!=null)for(File f:files)if(f.isFile()&&(f.getName().endsWith(".part")||f.getName().endsWith(".video")))total=PhoneReady.add(total,f.length());}return total;}
 static String storage(DownloadStore store,PhoneReady p,String id,long total){JSONArray jobs=store.diskJobs();return PhoneReady.storageReason(used(store),PhoneReady.reserved(jobs,id),total<=0?-1:Math.max(0,total-store.safeLength(id)),p.budget(),new StatFs(store.directory.getAbsolutePath()).getAvailableBytes());}
 static String episodeKey(JSONObject i){return (!i.optString("imdb").isEmpty()?i.optString("imdb"):i.optString("group",i.optString("id")))+":"+i.optInt("season")+":"+i.optInt("episode");}
 static List<Map<String,Boolean>> otherProgress(DataStore data){List<Map<String,Boolean>> result=new ArrayList<>();try{for(JSONObject profile:DataStore.objects(data.profiles.list())){String id=profile.optString("id");if(id.equals(data.profileId))continue;Map<String,Boolean> done=new HashMap<>();for(JSONObject i:DataStore.objects(NoirApp.dataFor(data.context,id).itemsShared())){String key=episodeKey(i);done.put(key,done.getOrDefault(key,true)&&PhoneReady.watched(i));}result.add(done);}}catch(Exception e){result.add(Collections.emptyMap());}return result;}
 static boolean otherUnfinished(JSONObject item,List<Map<String,Boolean>> profiles){if(item==null)return true;String key=episodeKey(item);for(Map<String,Boolean> profile:profiles)if(!profile.getOrDefault(key,false))return true;return false;}
 void cleanup(DataStore data,DownloadStore store,PhoneReady p)throws Exception{if(!p.cleanup()){for(JSONObject r:DataStore.objects(p.removals()))p.forgetRemoval(r.optString("id"));return;}Map<String,JSONObject> items=new HashMap<>();for(JSONObject i:DataStore.objects(data.itemsShared()))items.put(i.optString("id"),i);Map<String,JSONObject> jobs=new HashMap<>();for(JSONObject j:DataStore.objects(store.jobs()))jobs.put(j.optString("id"),j);List<Map<String,Boolean>> other=otherProgress(data);long now=System.currentTimeMillis();for(JSONObject j:jobs.values()){String id=j.optString("id");JSONObject item=items.get(id);if(j.optBoolean("readyManaged")&&j.optString("status").equals("complete")&&!store.ownsReadyFile(j)){p.protect(id,false);p.log(id,"File changed; removal cancelled");continue;}if(store.ownsReadyFile(j)&&PhoneReady.cleanupEligible(j,item,p.cleanup(),false,p.protectedFile(id))){long at=PhoneReady.watchedAt(item);if(at>0&&!otherUnfinished(item,other))p.scheduleRemoval(id,at,now);else p.forgetRemoval(id);}else p.forgetRemoval(id);}
  for(JSONObject r:DataStore.objects(p.removals())){if(stopped||!allowed(data,store).isEmpty())return;String id=r.optString("id");JSONObject j=jobs.get(id),item=items.get(id);if(j!=null&&store.ownsReadyFile(j)&&PhoneReady.cleanupEligible(j,item,p.cleanup(),otherUnfinished(item,other),p.protectedFile(id))&&r.optLong("at")<=now&&PhoneReady.watchedAt(item)>0&&PhoneReady.watchedAt(item)+PhoneReady.SEVEN_DAYS<=now){synchronized(store){synchronized(data){synchronized(p){JSONObject fresh=data.item(id),freshJob=store.job(id);if(stopped||!allowed(data,store).isEmpty()||freshJob==null||!store.ownsReadyFile(freshJob)||!PhoneReady.cleanupEligible(freshJob,fresh,p.cleanup(),otherUnfinished(fresh,other),p.protectedFile(id))||PhoneReady.watchedAt(fresh)<=0||PhoneReady.watchedAt(fresh)+PhoneReady.SEVEN_DAYS>now)continue;store.remove(id);p.forgetRemoval(id);p.log(id,"Removed watched Ready copy");}}}}}
 }
}
